PointerRNA SpaceSequenceEditor_annotation_get(PointerRNA *ptr)
{
    SpaceSeq *data = (SpaceSeq *)(ptr->data);
    return RNA_pointer_create_with_parent(*ptr, RNA_Annotation, data->gpd);
}

void SpaceSequenceEditor_annotation_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    SpaceSeq *data = (SpaceSeq *)(ptr->data);
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }

    if (data->gpd) {
        id_us_min((ID *)data->gpd);
    }
    if (value.data) {
        id_us_plus((ID *)value.data);
    }
    *(void **)&data->gpd = value.data;
}

