PointerRNA SpaceView3D_region_3d_get(PointerRNA *ptr)
{
    PropPointerGetFunc fn = rna_SpaceView3D_region_3d_get;
    return fn(ptr);
}

static PointerRNA SpaceView3D_region_quadviews_get(CollectionPropertyIterator *iter)
{
    PropCollectionGetFunc fn = rna_SpaceView3D_region_quadviews_get;
    return fn(iter);
}

void SpaceView3D_region_quadviews_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_SpaceView3D_region_quadviews;

    PropCollectionBeginFunc fn = rna_SpaceView3D_region_quadviews_begin;
    fn(iter, ptr);

    if (iter->valid) {
        iter->ptr = SpaceView3D_region_quadviews_get(iter);
    }
}

void SpaceView3D_region_quadviews_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_iterator_listbase_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = SpaceView3D_region_quadviews_get(iter);
    }
}

void SpaceView3D_region_quadviews_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_listbase_end;
    fn(iter);
}

bool SpaceView3D_region_quadviews_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    SpaceView3D_region_quadviews_begin(&iter, ptr);

    if (iter.valid) {
        ListBaseIterator *internal = &iter.internal.listbase;
        if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_listbase_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            while (index-- > 0 && internal->link) {
                internal->link = internal->link->next;
            }
            found = (index == -1 && internal->link);
        }
        if (found) { *r_ptr = SpaceView3D_region_quadviews_get(&iter); }
    }

    SpaceView3D_region_quadviews_end(&iter);

    return found;
}

