void SpreadsheetColumnID_name_get(PointerRNA *ptr, char *value)
{
    SpreadsheetColumnID *data = (SpreadsheetColumnID *)(ptr->data);
    if (data->name == nullptr) {
        *value = '\0';
        return;
    }
    strcpy(value, data->name);
}

int SpreadsheetColumnID_name_length(PointerRNA *ptr)
{
    SpreadsheetColumnID *data = (SpreadsheetColumnID *)(ptr->data);
    return (data->name == nullptr) ? 0 : strlen(data->name);
}

void SpreadsheetColumnID_name_set(PointerRNA *ptr, const char *value)
{
    SpreadsheetColumnID *data = (SpreadsheetColumnID *)(ptr->data);
    if (data->name != nullptr) { MEM_delete(data->name); }
    const size_t length = strlen(value);
    if (length > 0) {
        data->name = MEM_new_array_uninitialized<char>(length + 1, __func__);
        memcpy(data->name, value, length + 1);
    } else { data->name = nullptr; }
}

